INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(162711,0,0,'Ya come to spoil de ritual...?',12,0,100,0,0,0,0,0,'Muzah - aggro'),
(162711,1,0,'Spider, Bat, Serpent. I fight wid de blessin\' of de Sinister Ones.',12,0,100,0,0,0,0,0,'Muzah - 90 %'),
(162711,2,0,'De Sinister Ones chose Hirsutta. And Hirsutta anointed me champion.',12,0,100,0,0,0,0,0,'Muzah - 40 %'),
(162711,3,0,'De loa be bringin\' forth in a bloody birth!',12,0,100,0,0,0,0,0,'Muzah - 10 %'),
(162711,4,0,'Shadra... Hir\'eek... Dambala... I offer ya my soul...',12,0,100,0,0,0,0,0,'Muzah - death'),
(162715,0,0,'Once, I ruled by favor of de Sinister Ones. Ah, how long it\'s been... Their schemes be measured in centuries.',12,0,100,0,0,0,0,0,'Drak\'math the Sinister King - rises from the pillar'),
(162715,1,0,'Flies, moths, little rats - welcome to de table where you be de feast.',12,0,100,0,0,0,0,0,'Drak\'math - aggro'),
(162715,2,0,'Dey always coveted de Other Side; envied Bwonsamdi and de rest. Dey seek to be loa of Death. And when dey rise, we who served dem in life an\' death... will rule over all other souls.',12,0,100,0,0,0,0,0,'Drak\'math - first pillar phase'),
(162715,3,0,'But...! You promised...! De bargain was...',12,0,100,0,0,0,0,0,'Drak\'math - death'),
(162716,0,0,'Food! More...',12,0,100,0,0,0,0,0,'Chimeric Embryo - aggro'),
(162716,1,0,'Sting! Spider, Trap! Mother Shadra. Stealth Murder. Gluttony...',12,0,100,0,0,0,0,0,'Chimeric Embryo - swirls'),
(162716,2,0,'We\'ll be... waiting... drooling.',12,0,100,0,0,0,0,0,'Chimeric Embryo - death'),
(162765,0,0,'You will not disturb the birth!',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
(162765,0,1,'Your lives will be sacrificed on its altar!',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
(162765,0,2,'You arrive too late.',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
(162765,0,3,'Devotion burns my spirit. Come, taste my fervor!',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
(162765,0,4,'As in life, so in death.',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
(162765,1,0,'I will be waiting... in the beast\'s belly.',12,0,100,0,0,0,0,0,'Interstitial Wanderer - death'),
(162765,1,1,'You cannot kill... what is already dead.',12,0,100,0,0,0,0,0,'Interstitial Wanderer - death'),
(162765,1,2,'The Three will bring me back.',12,0,100,0,0,0,0,0,'Interstitial Wanderer - death'),
(162765,1,3,'With my last breath I curse you...',12,0,100,0,0,0,0,0,'Interstitial Wanderer - death'),
(162765,1,4,'Spirits of the Spider, the Bat, and the Serpent. Forgive me, I have failed you...',12,0,100,0,0,0,0,0,'Interstitial Wanderer - death'),
(162776,0,0,'You will not disturb the birth!',12,0,100,0,0,0,0,0,'Interstitial Wanderer - aggro'),
